+	// Write to a temporary file next to the original and rename it over, so a failed write never leaves the
+	// user with an empty or half-written config file.
+	tmp, err := os.CreateTemp(filepath.Dir(path), filepath.Base(path)+"-fmt")
+	if err != nil {
+		return err
+	}
+	if _, err := tmp.Write(result); err != nil {
+		tmp.Close()
+		return err
+	}
+	if err := tmp.Close(); err != nil {
+		os.Remove(tmp.Name())
+		return err
+	}
+	return os.Rename(tmp.Name(), path)
 }
